svg.script:
(function(){
  const svg = document.documentElement;
  const info = svg.getElementById('info_text');
  svg.querySelectorAll('.component').forEach(function(el){
    el.addEventListener('click', function(evt){
      evt.stopPropagation();
      svg.querySelectorAll('.component').forEach(function(x){ x.classList.remove('is-selected'); });
      el.classList.add('is-selected');
      const name = el.getAttribute('data-component') || el.id;
      if(info) info.textContent = 'Selezionato: ' + name + '  |  id="' + el.id + '"';
      svg.dispatchEvent(new CustomEvent('configurator:select', {
        bubbles: true,
        detail: { id: el.id, component: name }
      }));
    });
  });
  svg.addEventListener('click', function(evt){
    if(evt.target === svg){
      svg.querySelectorAll('.component').forEach(function(x){ x.classList.remove('is-selected'); });
      if(info) info.textContent = 'Clicca un componente per selezionarlo';
    }
  });
})();
